          <p class="text-slate-600 text-sm">Save the Opportunity and confirm it appears in the correct stage.</p>
        </div>
      </div>
    </div>
  </div>
</div>',
      title = 'Creating a Sample Opportunity',
      lesson_number = 6,
      sort_order = 6,
      updated_at = NOW()
    WHERE id = v_lesson_id;
    
    RAISE NOTICE 'Updated lesson: Creating a Sample Opportunity';
  END IF;

END $$;


-- Insert Quiz Questions for Lesson: Creating a Sample Opportunity

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 5 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 5 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'creating-sample-opportunity' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson creating-sample-opportunity not found in module 5';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the first step in creating an Opportunity?', 
    '["Add a note","Go to the Opportunities area","Send an email","Delete the contact"]'::jsonb,
    'Go to the Opportunities area',
    'The first step is to go to the Opportunities area in LeadProspectrr, then choose the correct pipeline and add a new Opportunity.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why add an estimated value to an Opportunity?', 
    '["It must be exactly correct","It helps you understand possible revenue in the pipeline","It automatically charges the client","It is required by law"]'::jsonb,
    'It helps you understand possible revenue in the pipeline',
    'The estimated value helps you understand possible revenue in your pipeline. It does not need to be perfect - it is for tracking and forecasting purposes.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should a good note include?', 
    '["Just the person''s name","Details about what they want, project scope, and next steps","Your personal opinions about the lead","Random thoughts"]'::jsonb,
    'Details about what they want, project scope, and next steps',
    'A good note includes details about what the lead asked for, project scope, timeline, and next steps. Example: ''Sarah asked about website redesign. Needs discovery call to understand scope and timeline.''', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
